        // @custom-variant theme-midnight {
        //   &:where([data-theme="midnight"] *) {
        //     @slot;
        //   }
        // }
        parse_rule_block(p);
    }

    Present(m.complete(p, TW_CUSTOM_VARIANT_AT_RULE))
}

fn parse_custom_variant_shorthand(p: &mut CssParser) -> ParsedSyntax {
    if !p.at(T!['(']) {
